// Job-search labels to fetch. Read-only test: no DB writes.
const DAYS = 30;
return [
  'Job Search/Application Updates',
  'Job Search/Interviews & Offers',
  'Job Search/Job Alerts',
].map(label => ({ json: { label, query: `label:"${label}" newer_than:${DAYS}d` } }));

// One clean record per message. Hermes consumes these; nothing is written anywhere.
return $input.all().map((item, i) => {
  const m = item.json;
  const header = (name) =>
    m[name] ?? m[name.toLowerCase()] ??
    m.payload?.headers?.find(h => h.name.toLowerCase() === name.toLowerCase())?.value ?? null;
  const date = m.internalDate ? new Date(Number(m.internalDate)).toISOString() : header('Date');
  return {
    json: {
      message_id: m.id,
      thread_id: m.threadId,
      label: $('Labels').itemMatching(i)?.json.label ?? null,
      date,
      from: header('From'),
      to: header('To'),
      subject: header('Subject'),
      snippet: m.snippet ?? null,
    },
  };
});
